% Updated value searchlights: direct adaptation of rsa_imagewise/aggregate_rsa_group.m.
% Edit the paths below as in the original workflow. This uses the same GM
% masking, 6 mm smoothing, persistent SPM one-sample model, and positive contrast.
% Only combined-phase odor_value maps in the three requested cue subsets are used.
% Run the staged copy beside subjects.txt generated by make_swarm.py.

%% ---------- Settings ----------
addpath('/Users/liuq13/Applications/spm12/');

base_dir = '/Users/liuq13/SPCD_data/rsa_maps';
analysis_subfolder = 'probe_imagewise_value_updated';

sessions = {'both'};

models = {'odor_value'};

% cue subset versions
%   subset-all = all cue maps
%   subset-conditioned_only = conditioned cue maps
%   subset-preconditioned_only = preconditioned cue maps
subset_tags = {'subset-all', 'subset-conditioned_only', 'subset-preconditioned_only'};

fwhm = 6; % smoothing kernel in mm

mask_file = '/Users/liuq13/SPCD_data/masks/gm_0.1.nii';
skip_subs = {'sub-19', 'sub-31', 'sub-33'};

subjects_file = fullfile(fileparts(mfilename('fullpath')), 'subjects.txt');
assert(exist(subjects_file, 'file') == 2, 'Generate the Swarm first to create subjects.txt.');
planned_subs = regexp(strtrim(fileread(subjects_file)), '\s+', 'split');
planned_subs = sort(planned_subs(~ismember(planned_subs, skip_subs)));
assert(numel(planned_subs) >= 2 && numel(unique(planned_subs)) == numel(planned_subs), ...
    'Expected at least two unique planned participants.');

%% ---------- Init SPM ----------
spm('Defaults','fMRI');
spm_jobman('initcfg');

analysis_root = fullfile(base_dir, analysis_subfolder);

Vm = spm_vol(mask_file);
M = spm_read_vols(Vm) > 0;

% Check every planned map before estimating any of the three group models.
% A failed/missing job is reported for investigation, never silently excluded.
for subseti = 1:numel(subset_tags)
    for subi = 1:numel(planned_subs)
        path = fullfile(analysis_root, 'both', sprintf('%s_model-odor_value_%s.nii.gz', ...
            planned_subs{subi}, subset_tags{subseti}));
        assert(exist(path, 'file') == 2, 'Missing planned map; inspect the corresponding job: %s', path);
    end
end


%% ---------- Combined-phase group analysis ----------
for si = 1:numel(sessions)
    session_tag = sessions{si};

    fprintf('\n============================================================\n');
    fprintf('>>> PER-SESSION GROUP ANALYSIS | SESSION: %s\n', session_tag);
    fprintf('============================================================\n');

    input_dir = fullfile(analysis_root, session_tag);
    assert(exist(input_dir, 'dir') == 7, 'Input folder not found: %s', input_dir);

    for subseti = 1:numel(subset_tags)
        subset_tag = subset_tags{subseti};

        subset_suffix = ['_' subset_tag];
        subset_label = subset_tag;

        fprintf('\n--- Subset version: %s ---\n', subset_label);

        for modeli = 1:numel(models)
            model_tag = models{modeli};

            pat = sprintf('sub-*_model-%s%s.nii.gz', ...
                model_tag, subset_suffix);

            all_gz = dir(fullfile(input_dir, pat));

            keep_idx = arrayfun(@(f) any(strcmp(regexp(f.name, '^sub-\d+', 'match', 'once'), planned_subs)), all_gz);
            all_gz = all_gz(keep_idx);
            assert(numel(all_gz) == numel(planned_subs), 'Group map count differs from subjects.txt.');

            fprintf('Pattern: %s\n', pat);
            fprintf('Found %d .nii.gz maps.\n', numel(all_gz));

            spm_model_dir = fullfile(input_dir, 'group_spm', ...
                sprintf('model-%s', model_tag), subset_tag);
            spm_input_dir = fullfile(spm_model_dir, 'spm_inputs');
            spm_mat_path = fullfile(spm_model_dir, 'SPM.mat');
            spmT_path = fullfile(spm_model_dir, 'spmT_0001.nii');

            if exist(spm_mat_path, 'file') || exist(spmT_path, 'file')
                error('SPM output already exists; use a fresh model folder before rerunning: %s', spm_model_dir);
            end

            if ~exist(spm_model_dir, 'dir')
                mkdir(spm_model_dir);
            end
            if ~exist(spm_input_dir, 'dir')
                mkdir(spm_input_dir);
            end

            fid = fopen(fullfile(spm_model_dir, 'participants.txt'), 'w');
            assert(fid ~= -1, 'Cannot save participant list.');
            fprintf(fid, '%s\n', planned_subs{:});
            fclose(fid);
            smoothed_files = cell(0,1);

            for fi = 1:numel(all_gz)
                gz_path = fullfile(all_gz(fi).folder, all_gz(fi).name);

                [~, gz_name, gz_ext] = fileparts(gz_path);
                if ~strcmp(gz_ext, '.gz')
                    error('Expected .nii.gz file, got: %s', gz_path);
                end

                % Fresh model inputs avoid reusing an old uncompressed map.
                nii_path = fullfile(spm_input_dir, gz_name);
                gunzip(gz_path, spm_input_dir);

                V = spm_vol(nii_path);
                assert(isequal(V.dim, Vm.dim) && max(abs(V.mat(:) - Vm.mat(:))) < 1e-5, ...
                    'Map/GM grid mismatch: %s', gz_path);
                Y = spm_read_vols(V);
                assert(all(isfinite(Y(M))), 'Nonfinite map values; inspect this participant: %s', gz_path);

                [~, base_name, ~] = fileparts(nii_path);
                fprintf('  Mask->NaN + smooth: %s\n', base_name);

                Y(~M) = NaN;

                masked_path = fullfile(spm_input_dir, ['c_' base_name '.nii']);
                Vc = V;
                Vc.fname = masked_path;
                spm_write_vol(Vc, Y);

                smooth_path = fullfile(spm_input_dir, ['s_' base_name '.nii']);
                spm_smooth(masked_path, smooth_path, [fwhm fwhm fwhm]);

                smoothed_files{end+1,1} = [smooth_path ',1']; %#ok<SAGROW>
            end

            con_name = sprintf('RSA %s | %s | model-%s > 0', ...
                session_tag, subset_label, model_tag);

            try
                matlabbatch = {};

                matlabbatch{1}.spm.stats.factorial_design.dir = {spm_model_dir};
                matlabbatch{1}.spm.stats.factorial_design.des.t1.scans = smoothed_files;

                matlabbatch{1}.spm.stats.factorial_design.cov = struct('c', {}, 'cname', {}, 'iCFI', {}, 'iCC', {});
                matlabbatch{1}.spm.stats.factorial_design.masking.tm.tm_none = 1;
                matlabbatch{1}.spm.stats.factorial_design.masking.im = 0;
                matlabbatch{1}.spm.stats.factorial_design.masking.em = {mask_file};

                matlabbatch{1}.spm.stats.factorial_design.globalc.g_omit = 1;
                matlabbatch{1}.spm.stats.factorial_design.globalm.gmsca.gmsca_no = 1;
                matlabbatch{1}.spm.stats.factorial_design.globalm.glonorm = 1;

                matlabbatch{2}.spm.stats.fmri_est.spmmat = {spm_mat_path};
                matlabbatch{2}.spm.stats.fmri_est.write_residuals = 0;
                matlabbatch{2}.spm.stats.fmri_est.method.Classical = 1;

                matlabbatch{3}.spm.stats.con.spmmat = {spm_mat_path};
                matlabbatch{3}.spm.stats.con.delete = 0;

                matlabbatch{3}.spm.stats.con.consess{1}.tcon.name    = con_name;
                matlabbatch{3}.spm.stats.con.consess{1}.tcon.weights = 1;
                matlabbatch{3}.spm.stats.con.consess{1}.tcon.sessrep = 'none';

                fprintf('Running persistent SPM batch: %s\n', spm_model_dir);
                spm_jobman('run', matlabbatch);

            catch ME
                fprintf('SPM error: %s\n', ME.message);
                rethrow(ME);
            end

            assert(exist(spmT_path, 'file') == 2, 'Expected spmT_0001.nii not found.');

            fprintf('Saved SPM group model: %s\n', spm_model_dir);
            fprintf('Open this SPM.mat in SPM Results: %s\n', spm_mat_path);
        end
    end
end

fprintf('\nAll three value group models complete.\n');
